const input = $input.first().json;
const jobTitle = String(input['Job Title'] ?? '').trim();
if (!jobTitle || jobTitle.length > 200) throw new Error('Enter a job title between 1 and 200 characters.');

const location = String(input.Location ?? '').trim().slice(0, 200);
const remotePreference = String(input['Remote Preference'] ?? 'Any').trim();
const workModelMap = { 'Remote only': [2], 'Onsite only': [1], 'Hybrid only': [3] };
if (!['Any', ...Object.keys(workModelMap)].includes(remotePreference)) throw new Error('Select a valid remote preference.');

const body = { jobTitle, country: 'US' };
if (location) {
  body.city = location;
  body.radiusRange = 25;
  body.locations = [{ city: location, radiusRange: 25 }];
}
if (workModelMap[remotePreference]) body.workModel = workModelMap[remotePreference];

return [{ json: { jobTitle, location, remotePreference, body } }];

const response = $input.first().json;
if (response.success !== true || !Array.isArray(response.result?.jobList)) {
  throw new Error(`Jobright search failed: ${response.errorMsg ?? 'unexpected response'}`);
}

const jobs = response.result.jobList.slice(0, 5).map((row, index) => {
  const job = row.jobResult ?? {};
  const company = row.companyResult ?? {};
  const id = String(job.jobId ?? '');
  return {
    rank: index + 1,
    jobId: id,
    jobTitle: String(job.jobTitle ?? 'View job'),
    company: String(company.companyName ?? job.userCompanyName ?? ''),
    location: Array.isArray(job.jobLocations) && job.jobLocations.length
      ? job.jobLocations.join(' · ')
      : String(job.jobLocation ?? ''),
    workModel: String(job.workModel ?? ''),
    employmentType: String(job.employmentType ?? ''),
    url: String(job.url ?? job.applyLink ?? job.originalUrl ?? (id ? `https://jobright.ai/jobs/info/${encodeURIComponent(id)}` : 'https://jobright.ai/jobs'))
  };
});

return [{ json: { jobs, jobCount: jobs.length, impId: response.result.impId ?? null } }];

const jobs = $input.first().json.jobs ?? [];
const criteria = $('Build search request').first().json;
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const safeUrl = value => {
  try {
    const url = new URL(String(value));
    return url.protocol === 'https:' ? url.toString() : 'https://jobright.ai/jobs';
  } catch {
    return 'https://jobright.ai/jobs';
  }
};

const cards = jobs.map(job => `
  <li style="border:1px solid #e4e4e7;border-radius:12px;padding:16px;margin:12px 0;list-style-position:inside">
    <a href="${escapeHtml(safeUrl(job.url))}" target="_blank" rel="noopener noreferrer" style="font-size:18px;font-weight:700;color:#6d28d9">${escapeHtml(job.jobTitle)}</a>
    <div style="margin-top:6px;font-weight:600">${escapeHtml(job.company)}</div>
    <div style="margin-top:4px;color:#52525b">${escapeHtml(job.location)}</div>
    <div style="margin-top:4px;color:#71717a;font-size:14px">${escapeHtml([job.workModel, job.employmentType].filter(Boolean).join(' · '))}</div>
  </li>`).join('');

const summary = [
  `Job title: ${criteria.jobTitle}`,
  criteria.location ? `Location: ${criteria.location}` : 'Location: United States',
  `Remote preference: ${criteria.remotePreference}`
].map(escapeHtml).join(' · ');

const html = `<main style="font-family:Inter,Arial,sans-serif;max-width:760px;margin:32px auto;padding:0 18px;color:#18181b">
  <h1>Relevant jobs from Jobright</h1>
  <p>${summary}</p>
  <p style="color:#52525b">These are search-based results, not personalized match scores.</p>
  ${jobs.length ? `<ol style="padding:0">${cards}</ol>` : '<p>No jobs were returned. Try a broader job title or location.</p>'}
  <p style="margin-top:24px"><a href="https://jobright.ai/jobs" target="_blank" rel="noopener noreferrer">Find more matching jobs on Jobright</a></p>
</main>`;

return [{ json: { html, jobs, query: criteria.body } }];

const item = $input.first().json;
const message = String(item.error?.message ?? item.message ?? 'The job search could not be completed.');
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
return [{ json: { html: `<main style="font-family:Inter,Arial,sans-serif;max-width:680px;margin:32px auto;padding:0 18px"><h1>Unable to search jobs</h1><p>${escapeHtml(message)}</p><p>Please revise the form and try again.</p></main>` } }];
